style.css:
/* Basic Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    font-family: 'Arial', sans-serif;
    background-color: #f0f8ff;
    color: #333;
    line-height: 1.6;
    padding: 20px;
}

/* Header Styling */
header {
    background: #4CAF50;
    color: white;
    padding: 10px 0;
    text-align: center;
    border-radius: 5px;
}

/* Navigation Styling */
nav ul {
    list-style: none;
    padding: 0;
}

nav ul li {
    display: inline;
    margin-right: 10px;
}

nav ul li a {
    text-decoration: none;
    color: white;
    padding: 5px 10px;
    background: #333;
    border-radius: 3px;
}

nav ul li a:hover {
    background: #555;
}

/* Main Content Styling */
main {
    margin-top: 20px;
}

main h1 {
    font-size: 2em;
    margin-bottom: 10px;
}

main p {
    margin-bottom: 10px;
}

/* Footer Styling */
footer {
    background: #333;
    color: white;
    text-align: center;
    padding: 10px 0;
    margin-top: 20px;
    border-radius: 5px;
}
